        qTryMetaTypeInterfaceForType(). If one of the types is not suitable,
        the function returns nullptr and the argument types will be looked up
        from the signal's QMetaMethod when the signal is first emitted.

        Whether a type is complete may differ between translation units for
        the same argument list, so the completeness check is parametrized by a
        type that is unique to each translation unit, preventing the linker
        from folding instantiations that made different decisions.
    */
    namespace {
    struct ConnectionTypesUniqueTag {};
    }

    template <typename ArgList, typename Unique = ConnectionTypesUniqueTag> struct ConnectionTypes;
    template <typename Unique> struct ConnectionTypes<List<>, Unique>
    { static const int *types() { return nullptr; } };
    template <typename... Args, typename Unique> struct ConnectionTypes<List<Args...>, Unique>
    {
        static const int *types()
        {
            const QMetaTypeInterface *ifaces[] = { qTryMetaTypeInterfaceForType<Unique, Args>()... };
            for (const QMetaTypeInterface *iface : ifaces) {
                if (!iface)
                    return nullptr;
            }
            static const int t[sizeof...(Args) + 1] = { QMetaType(qTryMetaTypeInterfaceForType<Unique, Args>()).id()..., 0 };
            return t;
        }
    };
}
